import { tasks } from "@trigger.dev/sdk/v3";

async function main() {
  const idempotencyKey = "idemp-key-" + Date.now();

  console.log("Triggering task 1 with idempotencyKey:", idempotencyKey);
  const handle1 = await tasks.trigger(
    "webhook-handler-resilient_webhook_idempotency__xKFoofz",
    { idempotencyKey, amount: 100 },
    { idempotencyKey }
  );
  console.log("Run ID 1:", handle1.id);

  console.log("Triggering task 2 with idempotencyKey:", idempotencyKey);
  const handle2 = await tasks.trigger(
    "webhook-handler-resilient_webhook_idempotency__xKFoofz",
    { idempotencyKey, amount: 100 },
    { idempotencyKey }
  );
  console.log("Run ID 2:", handle2.id);
}

main().catch(console.error);

